import json
import boto3
lambda_client = boto3.client('lambda')
s3_client = boto3.client('s3')

def invoke_object_processor_lambda(function_name: str, bucket: str, key: str) -> dict:
    payload = {'bucket': bucket, 'key': key}
    response = lambda_client.invoke(FunctionName=function_name, InvocationType='RequestResponse', Payload=json.dumps(payload).encode('utf-8'))
    raw = response['Payload'].read().decode('utf-8')
    result = {'function': function_name, 'status_code': response['StatusCode'], 'payload_sent': payload, 'response': raw}
    if 'FunctionError' in response:
        result['error'] = response['FunctionError']
    # Remove the source object once it has been processed successfully
    if 'FunctionError' not in response and response['StatusCode'] == 200:
        s3_client.delete_object(Bucket=bucket, Key=key)
        result['source_deleted'] = True
    return result
